import { randomBytes, createHmac, scryptSync, timingSafeEqual } from 'node:crypto';

// Devydtz Office - Railway Function (Bun). Single-owner workspace, volume-backed SQLite.
const ENV = process.env;
const HOSTNAME = '0.0.0.0';
const PORT = Number(ENV.PORT || 3000);
const SESSION_SECRET = ENV.OFFICE_SESSION_SECRET || (ENV.OFFICE_TEST === '1' ? 'test-secret-not-for-deployment-at-all' : '');
const HASH = ENV.OFFICE_PASSWORD_HASH || '';
const SALT = ENV.OFFICE_PASSWORD_SALT || '';
const DEMO = ENV.OFFICE_TEST === '1';
// Independent pairing credential for authorized Windows workers; never a ChatGPT token.
const BRIDGE_SECRET = ENV.OFFICE_BRIDGE_TOKEN || (DEMO ? 'office-bridge-test-only-secret-0123456789' : '');
const bridgeReady = BRIDGE_SECRET.length >= 32;
function matchesBridge(req) {
  if (!bridgeReady) return false;
  const authorization=req.headers.get('authorization')||'';
  if (!authorization.startsWith('Bearer ')) return false;
  const supplied=authorization.slice(7);
  if (supplied.length!==BRIDGE_SECRET.length) return false;
  return timingSafeEqual(Buffer.from(supplied),Buffer.from(BRIDGE_SECRET));
}
if (!DEMO && (!SESSION_SECRET || SESSION_SECRET.length < 40 || !HASH || !SALT)) throw new Error('Set OFFICE_PASSWORD_HASH, OFFICE_PASSWORD_SALT and OFFICE_SESSION_SECRET before starting.');

const originalEmployees = [
  { id:'devy',name:'Devy',role:'Boss',focus:'Work coordination, priorities, and approvals',symbol:'◆' },
  { id:'atlas',name:'Atlas',role:'Development',focus:'Coding, troubleshooting, and pull-request reviews',symbol:'⌘' },
  { id:'ops',name:'Ops',role:'Infrastructure',focus:'Deployments, monitoring, and service incidents',symbol:'⌁' },
  { id:'cipher',name:'Cipher',role:'Security',focus:'Security reviews and vulnerability assessment',symbol:'◇' },
  { id:'scout',name:'Scout',role:'Research',focus:'Documentation, sources, and technical research',symbol:'◎' },
  { id:'bantay',name:'Bantay',role:'Game operations',focus:'Moderation review and Roblox operations',symbol:'▣' },
];
const blankState = () => ({v:2, tasks:[], jobs:[], bridge:{lastSeen:0}, messages:[{id:'intro',by:'boss',text:'Tell me what needs to get done. I can create and assign tasks, show pending work, and help organize your office.',at:new Date().toISOString()}], events:[], projects:[{id:'portfolio',name:'Devydtz',url:'https://devydtz.com',repo:'Devydtz-space/devydtz-world'}]});
let memory = blankState();
let db = null;
if (!DEMO) {
  const { Database } = await import('bun:sqlite');
  db = new Database('/data/devydtz-office.sqlite', {create:true, strict:true});
  db.exec('PRAGMA journal_mode=WAL; PRAGMA busy_timeout=5000; CREATE TABLE IF NOT EXISTS app_state (id TEXT PRIMARY KEY, data TEXT NOT NULL)');
}
const selectState = db?.prepare('SELECT data FROM app_state WHERE id = ?');
const insertState = db?.prepare('INSERT INTO app_state(id,data) VALUES (?,?) ON CONFLICT(id) DO UPDATE SET data=excluded.data');
function load() {const found=selectState?.get('main');const state=found ? JSON.parse(found.data) : structuredClone(memory);state.jobs??=[];state.bridge??={lastSeen:0};return state}
function save(s){if(insertState) insertState.run('main',JSON.stringify(s));else memory=structuredClone(s)}
const now=()=>new Date().toISOString();
const uuid=()=>crypto.randomUUID();
const safeText=(value,limit=500)=>String(value??'').trim().slice(0,limit);
const isStatus=(v)=>['todo','doing','review','done'].includes(v);
const isPriority=(v)=>['normal','high','urgent'].includes(v);
function audit(state,action,summary){state.events.unshift({id:uuid(),action,summary,at:now()});state.events=state.events.slice(0,600)}
function json(data,status=200,headers={}){return new Response(JSON.stringify(data),{status,headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store',...headers}})}
function err(message,status=400){return json({error:message},status)}
function b64(v){return Buffer.from(v).toString('base64url')}
function mac(value){return createHmac('sha256',SESSION_SECRET).update(value).digest('base64url')}
function token(){const body=b64(JSON.stringify({sub:'owner',iat:Date.now(),exp:Date.now()+7*864e5}));return body+'.'+mac(body)}
function cookie(req){const raw=req.headers.get('cookie')||'';return raw.split(';').map(x=>x.trim()).find(x=>x.startsWith('office_session='))?.split('=').slice(1).join('=')||''}
function session(req){const t=cookie(req);const [body,sig]=t.split('.');if(!body||!sig)return null;const wanted=mac(body);if(sig.length!==wanted.length||!timingSafeEqual(Buffer.from(sig),Buffer.from(wanted)))return null;try{const p=JSON.parse(Buffer.from(body,'base64url').toString());return p.sub==='owner' && p.exp>Date.now()?t:null}catch{return null}}
function csrf(t){return mac('csrf:'+t)}
function sameOrigin(req){const ori=req.headers.get('origin');if(!ori)return true;const url=new URL(req.url);return ori===url.origin}
function verifyPassword(value){if(DEMO) return value==='test-password';if(!SALT||!HASH) return false;const actual=scryptSync(value,SALT,64);const wanted=Buffer.from(HASH,'hex');return wanted.length===64&&timingSafeEqual(actual,wanted)}
const ratelimit=new Map();
function loginLimit(ip){const old=ratelimit.get(ip)||{count:0,until:0};const t=Date.now();if(old.until<t){ratelimit.set(ip,{count:0,until:t+15*60e3});return false}return old.count>=10}
function failLogin(ip){const v=ratelimit.get(ip)||{count:0,until:Date.now()+15*60e3};v.count++;ratelimit.set(ip,v)}
function secureHeaders(headers={}){return {'x-content-type-options':'nosniff','x-frame-options':'DENY','referrer-policy':'no-referrer','permissions-policy':'camera=(), geolocation=(), microphone=(self)','strict-transport-security':'max-age=31536000; includeSubDomains',...headers}}
function getTask(s,id){return s.tasks.find(t=>t.id===id)}
function basicResult(s){return {tasks:s.tasks,employees:originalEmployees,events:s.events.slice(0,100),projects:s.projects,messages:s.messages.slice(-100),bridge:{paired:bridgeReady,online:Boolean(s.bridge?.lastSeen && Date.now()-s.bridge.lastSeen < 45000)},jobs:s.jobs.slice(-100).map(j=>({id:j.id,taskId:j.taskId,status:j.status,reply:j.reply||'',error:j.error||'',created:j.created,updated:j.updated}))}}
const limitBody = async(req)=>{const cl=Number(req.headers.get('content-length')||0);if(cl>30000)throw Error('Request too large');const body=await req.text();if(body.length>30000)throw Error('Request too large');return JSON.parse(body||'{}')};
const storeMessage=(s,by,text)=>{s.messages.push({id:uuid(),by,text:safeText(text,10000),at:now()});s.messages=s.messages.slice(-500)};
function bossRespond(s,message){const low=message.toLowerCase().trim();
  const m=message.match(/^(?:create|add|make)\s+(?:a\s+)?task\s+(?:for|to)\s+(atlas|ops|cipher|scout|bantay|devy)\s*[:,-]\s*(.{3,})$/i);
  if(m){const title=safeText(m[2],160);const t={id:uuid(),title,description:'',employee:m[1].toLowerCase(),project:'portfolio',status:'todo',priority:'normal',created:now(),updated:now(),due:'',notes:[]};s.tasks.unshift(t);audit(s,'task.created',`${t.title} assigned to ${m[1]}`);return `Created “${title}” and assigned it to ${m[1]}. You can open it in Work to add details.`}
  if(/(what|show|list|check|how many).*(review|approval)/.test(low)){const l=s.tasks.filter(t=>t.status==='review');return l.length?`${l.length} task${l.length===1?' is':'s are'} waiting for review: ${l.slice(0,5).map(t=>t.title).join('; ')}.`:'No tasks are waiting for review.'}
  if(/(show|list|what|status|how many|pending|today).*(task|work|do)/.test(low)){const open=s.tasks.filter(t=>t.status!=='done');return open.length?`You have ${open.length} open task${open.length===1?'':'s'}. ${open.slice(0,5).map(t=>`${t.title} (${t.status==='todo'?'To do':t.status==='doing'?'In progress':'Review'})`).join('; ')}.`:'No open tasks. Create one in Work or say “Create task for Atlas: Review the website.”'}
  if(/(help|what can you do|commands)/.test(low))return 'I can create tasks, assign employees, and summarize work. Try “Create task for Atlas: Check the website”, “Show my tasks”, or “What needs review?”. For open-ended AI conversations, configure an AI provider in Railway.';
  return null;
}
async function modelAnswer(s,message){const key=ENV.OFFICE_GEMINI_API_KEY; if(!key)return null;const model=ENV.OFFICE_GEMINI_MODEL||'gemini-2.5-flash';if(!/^[a-zA-Z0-9._-]+$/.test(model))throw Error('Invalid model configuration');const context=s.tasks.slice(0,15).map(t=>({title:t.title,assignee:t.employee,status:t.status}));const body={systemInstruction:{parts:[{text:'You are Devy, a concise development office coordinator. Do not claim you executed any tools, deployments, or PC actions. Do not reveal credentials. Respond accurately, and say when information is unknown.'}]},contents:[{role:'user',parts:[{text:`Current task summary: ${JSON.stringify(context)}\n\nUser: ${message}`}]}],generationConfig:{maxOutputTokens:350,temperature:0.3}};const ac=new AbortController();const timer=setTimeout(()=>ac.abort(),20000);try{const res=await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent`,{method:'POST',headers:{'content-type':'application/json','x-goog-api-key':key},body:JSON.stringify(body),signal:ac.signal});if(!res.ok)throw Error(`AI provider unavailable (${res.status})`);const d=await res.json();return d.candidates?.[0]?.content?.parts?.map(p=>p.text||'').join('')||'No response returned by model.'}finally{clearTimeout(timer)}}

